def choose_move(observation):
    pos = observation.get("self_position", {})
    x = pos.get("x", 0)
    y = pos.get("y", 0)

    opp = observation.get("opponent_position", {})
    ox = opp.get("x", 0)
    oy = opp.get("y", 0)

    width = observation.get("grid_width", 1)
    height = observation.get("grid_height", 1)

    best_dx = 0
    best_dy = 0

    obstacles = observation.get("obstacles", [])
    obs_set = set((o.get("x"), o.get("y")) for o in obstacles if o.get("x") is not None and o.get("y") is not None)

    targets = []
    for key in ("resources", "remaining_resource_count", "scores"):
        items = observation.get(key, [])
        if isinstance(items, list):
            for it in items:
                tx = it.get("x")
                ty = it.get("y")
                if tx is not None and ty is not None:
                    targets.append((tx, ty))

    best_dist = float("inf")
    for tx, ty in targets:
        dx = 0 if tx == x else (1 if tx > x else -1)
        dy = 0 if ty == y else (1 if ty > y else -1)
        dist = abs(tx - x) + abs(ty - y)
        if dist < best_dist and (x + dx, y + dy) not in obs_set:
            best_dist = dist
            best_dx, best_dy = dx, dy

    if best_dist < float("inf"):
        nx, ny = x + best_dx, y + best_dy
        if 0 <= nx < width and 0 <= ny < height:
            return [best_dx, best_dy]

    # Fallback: move away from opponent if colliding possibility
    dx = 0
    dy = 0
    if ox == x:
        dx = -1 if y < oy else 1
    elif ox > x:
        dx = -1
    else:
        dx = 1
    if oy == y:
        dy = -1 if x < ox else 1
    elif oy > y:
        dy = -1
    else:
        dy = 1

    nx, ny = x + dx, y + dy
    if 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obs_set:
        return [dx, dy]

    return [0, 0]
